# Let's verify by checking the actual symbols at those addresses with nm
# For the SGen worker thread, let's find what function contains 0x2f4b20 and 0x2f4c84
llvm-nm --defined-only /tmp/libmonosgen-2.0.so.debug 2>/dev/null | sort | awk -v addr1="2f4b20" -v addr2="2f4c84" '
{
  if ($1 <= addr1) prev1 = $0
  if ($1 <= addr2) prev2 = $0
}
END {
  print "0x2f4b20 is in: " prev1
  print "0x2f4c84 is in: " prev2
}'

