arguments.command:
# nm isn't showing text symbols well. Let's use readelf/objdump to look up dynamic symbols
objdump -t /tmp/libmonosgen-2.0.so.debug 2>/dev/null | awk '$1 != "" { addr = strtonum("0x"$1); size = ($1 ~ /^[0-9a-f]/) ? strtonum("0x"$5) : 0 }' | head -1
# Better approach: use the dynsym
objdump --syms /tmp/libmonosgen-2.0.so.debug 2>/dev/null | grep " F " | sort | awk '
{
  addr = strtonum("0x"$1)
  if (addr <= 0x2f4b20) { prev1_addr = $1; prev1_name = $NF }
  if (addr <= 0x2f4c84) { prev2_addr = $1; prev2_name = $NF }
}
END {
  print "0x2f4b20 -> " prev1_name " (at 0x" prev1_addr ")"
  print "0x2f4c84 -> " prev2_name " (at 0x" prev2_addr ")"
}' 2>/dev/null

