{"command": "# Good! 0x2c1a40 is in pin_major_object, confirmed.
# For the SGen worker thread addresses, they fall in the errata thunk range.
# Let me check what functions those thunks actually redirect to
readelf -sW /tmp/libmonosgen-2.0.so.debug 2>/dev/null | grep -i "FUNC" | sort -k2 | awk '
{
  addr = strtonum("0x"$2)
  size = strtonum($3) + 0
  if (addr <= 0x2f4b20 && (addr + size) > 0x2f4b20) print "0x2f4b20: " $8 " (0x"$2" size="$3")"
  if (addr <= 0x2f4c84 && (addr + size) > 0x2f4c84) print "0x2f4c84: " $8 " (0x"$2" size="$3")"
}' | head -10", "description": "Find functions for SGen worker addresses"}
